UPDATE ingredient SET public_summary = 'Ebenezer Harold Fuller "Ginger" Owers (21 October 1888 – June 1951) was an English footballer who played as a centre forward. He made over 90 appearances in the Football League and over 30 appearances in the Scottish League in the years prior to the First World War.', image_url = 'https://foodpowderindia.com/wp-content/uploads/2024/06/ginger1.jpg' WHERE slug = 'ginger-powder';
UPDATE ingredient SET public_summary = 'Cloves are the aromatic flower buds of a tree in the family Myrtaceae, Syzygium aromaticum (). They are native to the Maluku Islands, or Moluccas, in Indonesia, and are commonly used as a spice, flavoring, or fragrance in consumer products, such as toothpaste, soaps, or cosmetics. Freshly harvested cloves are available throughout the year owing to different harvest seasons across various countries.', image_url = 'https://boreddaddy.com/wp-content/uploads/2025/07/66ff0566b3eef39b517ad7b5_66aa859.webp' WHERE slug = 'clove';
UPDATE ingredient SET public_summary = 'A raisin is a dried grape. Raisins are produced in many regions of the world and may be eaten raw or used in cooking, baking, and brewing. The word raisin is commonly used for the dried dark-colored seedless grape, while sultana is a golden-colored dried grape, and currant is a dried small Black Corinth seedless grape.', image_url = 'https://thecoconutmama.com/wp-content/uploads/2024/03/shutterstock_280639877-scaled.jpg' WHERE slug = 'raisins';
