UPDATE ingredient SET public_summary = 'Soy sauce (sometimes called soya sauce in British English) is a liquid condiment of Chinese origin, traditionally made from a fermented paste of soybeans, roasted grain, brine, and Aspergillus oryzae or Aspergillus sojae molds (kōji). It is recognized for its saltiness and pronounced umami taste.
Soy sauce was created in its current form about 2,200 years ago during the Western Han dynasty of ancient China. Since then, it has become an important ingredient in East and Southeast Asian cooking as well as a condiment worldwide.', image_url = 'https://cookingformysoul.com/wp-content/uploads/2026/04/ingredients-soy-sauce-chicken-min-1024x1536.jpg' WHERE slug = 'soy-sauce';
UPDATE ingredient SET public_summary = 'No verified summary currently available for this ingredient.', image_url = 'https://galaxyflavours.com/cdn/shop/files/malted-milk-food-flavouring-1-litre_1445x.png?v=1777104346' WHERE slug = 'artificial-flavouring-substances-milk';
UPDATE ingredient SET public_summary = 'Condensed milk is cow''s milk from which water has been removed (roughly 60% of it). It is most often found with sugar added, in the form of sweetened condensed milk, to the extent that the terms "condensed milk" and "sweetened condensed milk" are often used interchangeably today. Sweetened condensed milk is a very thick, sweet product, which when canned can last for years without refrigeration if not opened. The product is used in numerous dessert dishes in many countries.
A related product is evaporated milk, which has undergone a lengthier preservation process because it is not sweetened.', image_url = 'https://images.openfoodfacts.org/images/products/408/860/015/5791/ingredients_en.12.full.jpg' WHERE slug = 'condensed-milk';
UPDATE ingredient SET public_summary = 'No verified summary currently available for this ingredient.', image_url = 'https://vasafoods.com/wp-content/uploads/2023/10/vasaoil-1024x1024.jpg' WHERE slug = 'refined-vegetable-oil';
UPDATE ingredient SET public_summary = 'Susan Jane Powter (born December 22, 1957) is an Australian-born American motivational speaker, nutritionist, personal trainer, and author, who rose to fame in the 1990s with her catchphrase "Stop the Insanity!", the centerpiece of her weight-loss infomercial. Powter has been described as a cross between Richard Simmons and Betty Friedan and "the Lenny Bruce of Wellness".
An advocate of a whole-foods, organic, low-fat diet, and regular cardiovascular and strength-training exercise, Powter also has condemned the diet industry. Her platinum-white close-cropped haircut, emphatic speaking manner, and habit of being barefoot while speaking in public, became trademarks of her celebrity.', image_url = 'https://onehotoven.com/wp-content/uploads/2024/06/powdered-sugar-labeled-1.jpg' WHERE slug = 'sugar-powder';
